(()=>{
 if(window.Capacitor?.isNativePlatform?.()||window.NativeStartup||!window.isSecureContext||!('serviceWorker' in navigator))return;
 const base=new URL('./',location.href);let deferred,hidden=false;
 const installed=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
 try{hidden=sessionStorage.getItem('upu-install-dismissed')==='1'}catch{}
 const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
 function dismiss(){hidden=true;document.querySelector('#pwa-install')?.remove();try{sessionStorage.setItem('upu-install-dismissed','1')}catch{}}
 function render(){if(installed()||hidden||(!ios&&!deferred)||document.querySelector('#pwa-install'))return;const main=document.querySelector('#main');if(!main)return;const box=document.createElement('aside');box.id='pwa-install';box.setAttribute('aria-label','Pasang aplikasi');box.style.cssText='display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:12px 16px;background:#fff5e9;border-bottom:1px solid #f0d6c7';const text=document.createElement('span');text.textContent='Pasang Kedai UPU di layar utama';text.style.flex='1';const button=document.createElement('button');button.type='button';button.className='btn';button.textContent='Pasang aplikasi';button.onclick=async()=>{if(deferred){const prompt=deferred;deferred=null;await prompt.prompt();const choice=await prompt.userChoice;if(choice.outcome==='accepted')dismiss();else box.remove()}else if(ios){const dialog=document.createElement('dialog');dialog.innerHTML='<h2>Pasang di iPhone / iPad</h2><p>Buka website ini di Safari, tekan Bagikan, lalu Tambahkan ke Layar Utama dan Tambah.</p><p>Buka dari ikon Kedai UPU di layar utama. Setelah masuk, tekan Aktifkan notifikasi browser jika ingin menerima pemberitahuan.</p><button type="button" class="btn primary">Mengerti</button>';dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal()}};const close=document.createElement('button');close.type='button';close.className='btn';close.textContent='Nanti';close.onclick=dismiss;box.append(text,button,close);main.before(box)}
 window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferred=event;render()});
 window.addEventListener('appinstalled',()=>{deferred=null;dismiss()});window.addEventListener('upu:ready',render);window.addEventListener('DOMContentLoaded',render);render();
 navigator.serviceWorker.register(new URL('push-sw.js',base).href,{scope:base.pathname,updateViaCache:'none'}).then(reg=>reg.update()).catch(()=>{console.warn('PWA belum terhubung. Muat ulang saat koneksi tersedia.')});
})();
